interface ParseResult {
    n: number;
    matrix: number[][];
    vector: number[];
}

export const parseMatrixText = (text: string): ParseResult => {
    if (!text.trim()) {
        throw new Error('Введите данные матрицы');
    }

    const lines = text.trim().split('\n')
        .map(line => line.trim())
        .filter(line => line.length > 0);

    if (lines.length < 2) {
        throw new Error('Должна быть хотя бы одна строка с размерностью и одна с данными');
    }

    const n = parseInt(lines[0]);
    if (isNaN(n) || n <= 0) {
        throw new Error('Первая строка должна содержать положительное целое число (размерность)');
    }
    if (n > 20) {
        throw new Error('Размерность матрицы не должна превышать 20');
    }

    if (lines.length - 1 !== n) {
        throw new Error(`Ожидалось ${n} строк с данными, получено ${lines.length - 1}`);
    }

    const matrix: number[][] = [];
    const vector: number[] = [];

    for (let i = 1; i <= n; i++) {
        const parts = lines[i].split(/\s+/).filter(p => p.length > 0);

        if (parts.length !== n + 1) {
            throw new Error(`Строка ${i} должна содержать ${n + 1} чисел (${n} коэффициентов + правую часть)`);
        }

        const row: number[] = [];
        for (let j = 0; j < parts.length; j++) {
            const cleanPart = parts[j].replace(',', '.');
            const val = parseFloat(cleanPart);
            if (isNaN(val)) {
                throw new Error(`Строка ${i}, элемент ${j + 1}: не число "${parts[j]}"`);
            }

            if (j < n) {
                row.push(val);
            } else {
                vector.push(val);
            }
        }
        matrix.push(row);
    }

    for (let i = 0; i < n; i++) {
        if (matrix[i].length !== n) {
            throw new Error(`Строка ${i + 1} матрицы содержит ${matrix[i].length} элементов, ожидалось ${n}`);
        }
    }

    return { n, matrix, vector };
};

export const formatMatrixToString = (matrix: number[][], vector: number[]): string => {
    const n = matrix.length;
    let result = n.toString() + '\n';

    for (let i = 0; i < n; i++) {
        const row = [...matrix[i], vector[i]];
        result += row.map(v => v.toString()).join(' ') + '\n';
    }

    return result.trim();
};
